// Ключи — только безопасный текст без запрещённых глифов, чтобы копирование памятки
// в Discord не срабатывало на автобан. (Генератор символов: scripts/resize-symbols.ps1 + generate-symbols.mjs)
export const SYMBOL_IMAGES: Record<string, string> = {
    "свастика": "data:image/png;base64,",
    "коловрат": "data:image/png;base64,",
    "чвк вагнер": "data:image/png;base64,",
    "valknut": "data:image/png;base64,",
    "железный крест": "data:image/png;base64,",
    "движение скинхедов": "data:image/png;base64,",
    "кельтский крест": "data:image/png;base64,",
    "талибан": "data:image/png;base64,",
    "vanguard america": "data:image/png;base64,",
    "атомваффен": "data:image/png;base64,",
    "ку-клукс-клан": "data:image/png;base64,",
    "ауе": "data:image/png;base64,",
    "флаг украинских националистов": "data:image/png;base64,",
    "zov": "data:image/png;base64,",
    "руны сс": "data:image/png;base64,",
    "символ азова": "data:image/png;base64,",
    "черное солнце": "data:image/png;base64,",
    "русское национальное единство": "data:image/png;base64,",
    "мертвая голова": "data:image/png;base64,",
    "руна одал": "data:image/png;base64,",
};

export function getSymbolImage(title: string): string | undefined {
    return SYMBOL_IMAGES[title.toLowerCase().replace(/ё/g, "е").replace(/[\u2014\u2013\u2015]/g, " ").replace(/[()|/]/g, " ").replace(/\s+/g, " ").trim()];
}
